def process(rolling_3month) -> pd.DataFrame:
    max_row = rolling_3month.loc[rolling_3month['Acres_Burned_3m'].idxmax()]
    return pd.DataFrame([{
        'Start_Date': max_row['Start_Date'],
        'End_Date': max_row['End_Date'],
        'Acres_Burned_3m': max_row['Acres_Burned_3m']
    }])
